#include <iostream>
using namespace std;

int main() {
    int lives = 3;              // whole numbers
    double price = 4.50;        // numbers with a decimal point
    bool gameOver = false;      // true or false, nothing else
    char grade = 'A';           // exactly one character

    cout << "Lives:     " << lives << endl;
    cout << "Price:     " << price << endl;
    cout << "Game over: " << gameOver << endl;
    cout << "Grade:     " << grade << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int temperature = -5;
    long long worldPopulation = 8100000000;
    double price = 249.99;
    float smaller = 2.5f;
    double pi = 3.14159265;

    cout << temperature << " and " << worldPopulation << endl;
    cout << price << " and " << smaller << endl;
    cout << pi << endl;
    return 0;
}

